    let Ω_F_A_s := LinearMap.range (evalMapRestricted A s)
    let B := Matrix.toBilin (Pi.basisFun F A) (1 : Matrix A A F)
    A.card = Module.finrank F ((Ω_F_A_s.dualAnnihilator).comap B) + dim A s

