    (hsol : IsSuitableWeakSolutionIntegrable Ω I q u Du p f)
    {z : ParabolicPoint} {r : ℝ} (hr : 0 < r)
    (hsub : closure (parabolicCylinder z.1 z.2 r) ⊆ spaceTimeSet Ω I) :
    IntegrableOn (fun w => |p w| ^ (3 / 2 : ℝ))
      (parabolicCylinder z.1 z.2 r) volume

theorem far_field_norm_sub_ge {x₀ x y : Vec3} {R : ℝ}
    (hx : 2 * R ≤ ‖x - x₀‖) (hy : ‖y - x₀‖ ≤ R) :
    ‖x - x₀‖ / 2 ≤ ‖x - y‖

theorem directional_smooth {g : Vec3 × ℝ → ℝ}
    (hg : ContDiff ℝ (⊤ : ℕ∞) g) (v : Vec3 × ℝ) :
    ContDiff ℝ (⊤ : ℕ∞) (fun z => fderiv ℝ g z v)

theorem integrable_product {F G : Vec3 × ℝ → ℝ}
    (hF : ContDiff ℝ (⊤ : ℕ∞) F) (hG : ContDiff ℝ (⊤ : ℕ∞) G)
    (hGc : HasCompactSupport G) : Integrable (fun z => F z * G z)

theorem spatial_eq_joint {g : Vec3 × ℝ → ℝ}
    (hg : ContDiff ℝ (⊤ : ℕ∞) g) (z : Vec3 × ℝ) (i : Fin 3) :
    spatialPartial g i z = fderiv ℝ g z (basisVec i, 0)

theorem spatial_smooth {F : Vec3 × ℝ → ℝ}
    (hF : ContDiff ℝ (⊤ : ℕ∞) F) (i : Fin 3) :
    ContDiff ℝ (⊤ : ℕ∞) (fun z : Vec3 × ℝ => spatialPartial F i z)

theorem spatial_support {F : Vec3 × ℝ → ℝ}
    (hF : ContDiff ℝ (⊤ : ℕ∞) F) (i : Fin 3) :
    tsupport (fun z : Vec3 × ℝ => spatialPartial F i z) ⊆ tsupport F

theorem time_eq_joint {g : Vec3 × ℝ → ℝ}
    (hg : ContDiff ℝ (⊤ : ℕ∞) g) (z : Vec3 × ℝ) :
    timePartial g z = fderiv ℝ g z (0, 1)

theorem time_support {F : Vec3 × ℝ → ℝ}
    (hF : ContDiff ℝ (⊤ : ℕ∞) F) :
    tsupport (fun z : Vec3 × ℝ => timePartial F z) ⊆ tsupport F

theorem integral_restrict_test {F G : Vec3 × ℝ → ℝ} {U : Set (Vec3 × ℝ)}
    (hsub : tsupport G ⊆ U) (hzero : ∀ z ∉ tsupport G, F z = 0) :
    (∫ z in U, F z) = ∫ z, F z

theorem spatial_zero {G : Vec3 × ℝ → ℝ}
    (hG : ContDiff ℝ (⊤ : ℕ∞) G) {z : Vec3 × ℝ}
    (hz : z ∉ tsupport G) (i : Fin 3) : spatialPartial G i z = 0

theorem time_zero {G : Vec3 × ℝ → ℝ}
    (hG : ContDiff ℝ (⊤ : ℕ∞) G) {z : Vec3 × ℝ}
    (hz : z ∉ tsupport G) : timePartial G z = 0

theorem singularSet_eq_diff (Ω : Set Vec3) (I : Set ℝ)
