theorem isSuitableWeakSolutionIntegrable_zero {Ω : Set Vec3} {I : Set ℝ} {q : ℝ}
    (hΩ : IsOpen Ω) (hI : IsOpen I) (hIc : OrdConnected I) (hq : 5 / 2 < q) :
