    IsWitness x y sideLH2 {(0, 0), (1, 0), (0, 1), (1, 1)}

theorem isWitness_lhl2 {x y : ℝ} (hx : 2 * hgap - sideLHL2 / 2 ≤ x) (hx' : x ≤ hgap)
    (hy : vgap - sideLHL2 / 2 ≤ y) (hy' : y ≤ vgap / 2) :
    IsWitness x y sideLHL2 {(0, 0), (1, 0), (2, 0), (0, 1), (1, 1), (2, 1)}

theorem ofReal_le_volume_levelSet (N : ℕ) {ε : ℝ} (hε : 0 < ε) :
    ENNReal.ofReal ((2 * N + 1) ^ 2 * (2 * hgap * vgap - 4 * (slotW * slotH))) ≤
      volume {z | ENNReal.ofReal (1 - 2 * ε) < maximalFunction (smeared N ε) z}

