    (h1 : b = ↑m₁ + ↑n₁ * s) (h2 : b * t = ↑m₂ + ↑n₂ * s) :
    ((m₁ * n₂ - n₁ * m₂ : ℤ) : ℝ) * s.im = Complex.normSq b * t.im

theorem diagQ_eval_eq_prod {m : ℕ} [NeZero m] {PhiQ : Polynomial (Polynomial ℚ)}
